1	/**
2	 * generate_pedagogy_corpus.ts
3	 *
4	 * Sovereignty Grounding Pipeline: Corpus Generation.
5	 *
6	 * This script scales the production of a high-fidelity dataset of [VERIFIED] entities
7	 * by iterating through the full RS3 cache dumps. It implements a two-track enrichment
8	 * strategy to preserve structural IDs while optimizing for API rate limits.
9	 *
10	 * Target: D:\sovereign\memory\pedagogy\corpus\verified_entities.jsonl
11	 */
12	
13	import { WikiEquipmentEnricher } from '../utils/WikiEquipmentEnricher.js';
14	import { resolveSovereignPath } from '../utils/SovereignPathResolver.js';
15	import { writeFileSync, mkdirSync, existsSync, readFileSync, appendFileSync } from 'fs';
16	import { join } from 'path';
17	import { createLogger } from '../utils/logger.js';
18	
19	const logger = createLogger('CorpusGenerator');
20	
21	// ═══════════════════════════════════════════════════════
22	// Configuration
23	// ═══════════════════════════════════════════════════════
24	
25	const CATALOG_PATHS = {
26	    items: 'D:/D-sovereign-/cache_pedagogy/json_dumps/items.json',
27	    npcs: 'D:/D-sovereign-/cache_pedagogy/json_dumps/npcs.json',
28	    quests: 'D:/D-sovereign-/memory/pedagogy/logic/quest_manifest.json'
29	};
30	
